  const builtHash = fs.existsSync(hashFile) ? (await promises.readFile(hashFile, "utf8")).trim() : "";
  if (!fs.existsSync(exe) || builtHash !== hash) {
    const sourceFile = path.join(dir, "CanonEdsdkHelper.cs");
    await promises.writeFile(sourceFile, helperSource, "utf8");
    const csc = cscPath();
    if (!fs.existsSync(csc)) throw new Error("Windows thiếu .NET Framework 4 (csc.exe) để dựng công cụ máy ảnh Canon");
    try {
